import {
  encodeDeployData,
  encodeFunctionData,
  getAddress,
  getContractAddress,
  keccak256,
  parseAbi,
  stringToHex,
  type Address,
  type Hex,
} from "viem";

import {
  SINGLETON_FACTORY_ADDRESS,
  singletonFactoryAbi,
} from "./standing-order-batch-executor.js";

export const GACHA_TABLE_KEEPER_EXECUTOR_SALT = keccak256(
  stringToHex("pull-pool-keeper/GachaTableKeeperExecutor/v1"),
);
export const GACHA_TABLE_KEEPER_EXECUTOR_DEPLOY_GAS_LIMIT = 600_000n;
export const GACHA_TABLE_KEEPER_EXECUTOR_MAX_DEFAULTS = 4;

export const gachaTableKeeperExecutorAbi = parseAbi([
  "constructor(address owner)",
  "function GACHA_TABLE() view returns (address)",
  "function MAX_DEFAULTS() view returns (uint256)",
  "function owner() view returns (address)",
  "function fireExact(uint256 battleId,uint256 minimumBounty) returns (uint256 bounty)",
  "function settleExact(uint256 battleId,uint256 minimumBounty) returns (uint256 bounty)",
  "function crankDefaultsExact(uint256 battleId,uint8[] legs,uint256 minimumBounty) returns (uint256 bounty)",
  "event RewardedExecution(bytes4 indexed selector,uint256 indexed battleId,uint256 calls,uint256 bounty)",
  "error EmptyBatch()",
  "error InvalidOwner()",
  "error PaymentFailed()",
  "error TooManyCalls()",
  "error Unauthorized()",
  "error UnauthorizedPayment()",
  "error UnexpectedBounty(uint256 actual,uint256 minimum)",
]);

// Generated from solc 0.8.28, Cancun, optimizer enabled with 1,000,000 runs.
export const GACHA_TABLE_KEEPER_EXECUTOR_BYTECODE = "" as Hex;
const GACHA_TABLE_KEEPER_EXECUTOR_RUNTIME_TEMPLATE = "" as Hex;
const OWNER_IMMUTABLE_OFFSETS = [333, 1396, 1582] as const;

function patchOwnerImmutable(template: Hex, owner: Address): Hex {
  const ownerWord = owner.slice(2).padStart(64, "0");
  let body = template.slice(2);
  for (const offset of OWNER_IMMUTABLE_OFFSETS) {
    const start = offset * 2;
    body = `${body.slice(0, start)}${ownerWord}${body.slice(start + 64)}`;
  }
  return `0x${body}`;
}

export function gachaTableKeeperExecutorDeployment(owner: Address): {
  readonly initCode: Hex;
  readonly address: Address;
  readonly expectedRuntimeCode: Hex;
  readonly expectedRuntimeCodeHash: Hex;
  readonly deployData: Hex;
} {
  const canonicalOwner = getAddress(owner);
  const initCode = encodeDeployData({
    abi: gachaTableKeeperExecutorAbi,
    bytecode: GACHA_TABLE_KEEPER_EXECUTOR_BYTECODE,
    args: [canonicalOwner],
  });
  const address = getContractAddress({
    from: SINGLETON_FACTORY_ADDRESS,
    opcode: "CREATE2",
    salt: GACHA_TABLE_KEEPER_EXECUTOR_SALT,
    bytecode: initCode,
  });
  const expectedRuntimeCode = patchOwnerImmutable(
    GACHA_TABLE_KEEPER_EXECUTOR_RUNTIME_TEMPLATE,
    canonicalOwner,
  );
  return {
    initCode,
    address,
    expectedRuntimeCode,
    expectedRuntimeCodeHash: keccak256(expectedRuntimeCode),
    deployData: encodeFunctionData({
      abi: singletonFactoryAbi,
      functionName: "deploy",
      args: [initCode, GACHA_TABLE_KEEPER_EXECUTOR_SALT],
    }),
  };
}

export function encodeGachaTableFire(
  battleId: bigint,
  minimumBounty: bigint,
): Hex {
  return encodeSingleGachaTableAction(
    "fireExact",
    battleId,
    minimumBounty,
  );
}

export function encodeGachaTableSettlement(
  battleId: bigint,
  minimumBounty: bigint,
): Hex {
  return encodeSingleGachaTableAction(
    "settleExact",
    battleId,
    minimumBounty,
  );
}

function encodeSingleGachaTableAction(
  functionName: "fireExact" | "settleExact",
  battleId: bigint,
  minimumBounty: bigint,
): Hex {
  if (battleId <= 0n || minimumBounty <= 0n) {
    throw new Error("invalid exact GachaTable action bounds");
  }
  return encodeFunctionData({
    abi: gachaTableKeeperExecutorAbi,
    functionName,
    args: [battleId, minimumBounty],
  });
}

export function encodeGachaTableDefaults(
  battleId: bigint,
  legs: readonly number[],
  minimumBounty: bigint,
): Hex {
  if (
    battleId <= 0n ||
    legs.length === 0 ||
    legs.length > GACHA_TABLE_KEEPER_EXECUTOR_MAX_DEFAULTS ||
    new Set(legs).size !== legs.length ||
    legs.some((leg) => !Number.isInteger(leg) || leg < 0 || leg >= 4) ||
    minimumBounty <= 0n
  ) {
    throw new Error("invalid exact GachaTable default batch");
  }
  return encodeFunctionData({
    abi: gachaTableKeeperExecutorAbi,
    functionName: "crankDefaultsExact",
    args: [battleId, legs, minimumBounty],
  });
}
